using Microsoft.AspNetCore.Mvc;using RaceDay.Mvc.Models;using RaceDay.Mvc.Services;
namespace RaceDay.Mvc.Controllers;
public class EventsController:Controller{readonly RaceDayApiClient api;public EventsController(RaceDayApiClient a)=>api=a;
public async Task<IActionResult> Index(string? search,string? type,string? location){var q=new List<string>();if(!string.IsNullOrWhiteSpace(search))q.Add("search="+Uri.EscapeDataString(search));if(!string.IsNullOrWhiteSpace(type))q.Add("type="+Uri.EscapeDataString(type));if(!string.IsNullOrWhiteSpace(location))q.Add("location="+Uri.EscapeDataString(location));ViewBag.Search=search;ViewBag.Type=type;ViewBag.Location=location;return View(await api.Get<List<EventSummary>>("api/events"+(q.Count>0?"?"+string.Join("&",q):""))??new());}
public async Task<IActionResult> Details(int id){var e=await api.Get<EventDetail>($"api/events/{id}");return e==null?NotFound():View(e);}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Enter(int eventId,int categoryId){if(HttpContext.Session.GetInt32("UserId")==null)return RedirectToAction("Login","Account");var r=await api.Send<object>(HttpMethod.Post,"api/enrolments",new{EventId=eventId,CategoryId=categoryId});TempData[r.Ok?"Success":"Error"]=r.Ok?"Event entry confirmed.":r.Message;return RedirectToAction(nameof(Details),new{id=eventId});}
bool Org()=>HttpContext.Session.GetString("Role")=="Organiser";IActionResult Gate()=>HttpContext.Session.GetInt32("UserId")==null?RedirectToAction("Login","Account"):Forbid();
public IActionResult Create()=>Org()?View(new EventVm()):Gate();
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(EventVm vm){if(!Org())return Gate();if(!ModelState.IsValid)return View(vm);var r=await api.Send<EventDetail>(HttpMethod.Post,"api/events",vm);if(!r.Ok){ModelState.AddModelError("",r.Message);return View(vm);}TempData["Success"]="Event created.";return RedirectToAction(nameof(Manage));}
public async Task<IActionResult> Manage(){if(!Org())return Gate();var all=await api.Get<List<EventSummary>>("api/events?includePast=true")??new();return View(all.Where(e=>e.OrganiserId==HttpContext.Session.GetInt32("UserId")).ToList());}
public async Task<IActionResult> Edit(int id){if(!Org())return Gate();var e=await api.Get<EventDetail>($"api/events/{id}");return e==null?NotFound():View(new EventVm{EventId=e.EventId,Name=e.Name,Description=e.Description,EventDate=e.EventDate,Location=e.Location,DistanceKm=e.DistanceKm,EventType=e.EventType});}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Edit(EventVm vm){if(!Org())return Gate();if(!ModelState.IsValid)return View(vm);var r=await api.Send<EventDetail>(HttpMethod.Put,$"api/events/{vm.EventId}",vm);if(!r.Ok){ModelState.AddModelError("",r.Message);return View(vm);}TempData["Success"]="Event updated.";return RedirectToAction(nameof(Manage));}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Delete(int id){if(!Org())return Gate();var r=await api.SendNoData(HttpMethod.Delete,$"api/events/{id}");TempData[r.Ok?"Success":"Error"]=r.Ok?"Event deleted.":r.Message;return RedirectToAction(nameof(Manage));}
[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>UploadBanner(int id,IFormFile file){if(!Org())return Gate();if(file==null||file.Length==0){TempData["Error"]="Select an image.";return RedirectToAction(nameof(Details),new{id});}var r=await api.Upload($"api/events/{id}/banner",file);TempData[r.Ok?"Success":"Error"]=r.Ok?"Banner uploaded.":r.Message;return RedirectToAction(nameof(Details),new{id});}}